#!/usr/bin/env python3
"""
patch-158-C — Customer detail page Assets section.

Third patch in the multi-asset arc. Adds CRUD for customer-attached
assets (bikes, vehicles, pets). Visible only when multi_asset_enabled
is on for the tenant. Single-modal create + edit flow.

What ships:
  - New CustomerAssetsController with store/update/archive/unarchive.
    All actions gated by tenant->multi_asset_enabled (abort_unless 404).

  - 4 new routes:
    POST   /customers/{id}/assets
    PATCH  /customers/{customerId}/assets/{id}
    POST   /customers/{customerId}/assets/{id}/archive
    POST   /customers/{customerId}/assets/{id}/unarchive

  - CustomerController::show loads active + archived assets when
    feature is on (no DB hit otherwise — same pattern as classes).

  - resources/views/tenant/customers/show.blade.php gains:
    * "Assets" card above the Memberships & Packs card
    * Empty state with prompt to add first asset
    * Grid of active assets with Edit/Archive actions per tile
    * Collapsible archived assets section with Restore
    * Single modal serves both create + edit (POST or PATCH method)
    * Vanilla JS for modal open/close + escape-to-close
    * Scoped CSS for the asset grid, tiles, and modal

Tenants without multi_asset_enabled see no change to the customer page.

Smoke test:
  1. Visit a customer detail page on a tenant with the flag on —
     "Assets" card should appear above Memberships & Packs.
  2. Click "+ Add asset", fill the modal, save — tile appears.
  3. Edit, archive, restore — all reload the page with success flash.
  4. Visit a customer page on a tenant with the flag OFF —
     no Assets card visible.

Standalone Python. Idempotent.
"""
